1	package api
2	
3	import (
4		"crypto/sha256"
5		"database/sql"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"net/http"
10		"net/http/httptest"
11		"path/filepath"
12		"strings"
13		"sync"
14		"testing"
15	
16		"github.com/xjeey8iust/sen-audit-ledger/internal/store"
17	)
18	
19	func openTestStore(t *testing.T) *store.Store {
20		t.Helper()
21		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
22		if err != nil {
23			t.Fatalf("open: %v", err)
24		}
25		t.Cleanup(func() { st.Close() })
26		return st
27	}
28	
29	func postEventBody(t *testing.T, router http.Handler, body string) *httptest.ResponseRecorder {
30		t.Helper()
31		recorder := httptest.NewRecorder()
32		request := httptest.NewRequest(http.MethodPost, "/events", strings.NewReader(body))
33		router.ServeHTTP(recorder, request)
34		return recorder
35	}
36	
37	func validEventBody() string {
38		return `{"account":"alice","operation":"login","resource":"console","result":"ok","occurred_at":"2026-10-05T08:30:00+08:00"}`
39	}
40	
41	func decodeEvent(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
42		t.Helper()
43		var decoded map[string]any
44		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
45			t.Fatalf("decode response: %v", err)
46		}
47		return decoded
48	}
49	
50	func wantHash(seq int64, account, operation, resource, result, occurredAt, prevHash string) string {
51		payload := fmt.Sprintf(`[%d,"%s","%s","%s","%s","%s","%s"]`, seq, account, operation, resource, result, occurredAt, prevHash)
52		sum := sha256.Sum256([]byte(payload))
53		return hex.EncodeToString(sum[:])
54	}
55	
56	func TestPostEventAppendsGenesisRecord(t *testing.T) {
57		router := NewRouter(openTestStore(t))
58	
59		recorder := postEventBody(t, router, validEventBody())
60		if recorder.Code != http.StatusCreated {
61			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusCreated, recorder.Body.String())
62		}
63		event := decodeEvent(t, recorder)
64	
65		if event["seq"] != float64(1) {
66			t.Fatalf("seq = %v, want 1", event["seq"])
67		}
68		if event["prev_hash"] != strings.Repeat("0", 64) {
69			t.Fatalf("prev_hash = %v, want 64 zeros", event["prev_hash"])
70		}
71		// occurred_at is stored and returned in UTC, fraction preserved.
72		if event["occurred_at"] != "2026-10-05T00:30:00Z" {
73			t.Fatalf("occurred_at = %v", event["occurred_at"])
74		}
75		want := wantHash(1, "alice", "login", "console", "ok", "2026-10-05T00:30:00Z", strings.Repeat("0", 64))
76		if event["hash"] != want {
77			t.Fatalf("hash = %v, want %v", event["hash"], want)
78		}
79	}
80	
81	func TestPostEventChainsRecords(t *testing.T) {
82		router := NewRouter(openTestStore(t))
83	
84		first := decodeEvent(t, postEventBody(t, router, validEventBody()))
85		second := decodeEvent(t, postEventBody(t, router,
86			`{"account":"bob","operation":"read","resource":"report","result":"denied","occurred_at":"2026-10-05T01:00:00.250Z"}`))
87	
88		if second["seq"] != float64(2) {
89			t.Fatalf("seq = %v, want 2", second["seq"])
90		}
91		if second["prev_hash"] != first["hash"] {
92			t.Fatalf("prev_hash = %v, want previous hash %v", second["prev_hash"], first["hash"])
93		}
94		if second["occurred_at"] != "2026-10-05T01:00:00.250Z" {
95			t.Fatalf("occurred_at = %v, fraction not preserved", second["occurred_at"])
96		}
97	}
98	
99	func TestPostEventKeepsOriginalFieldText(t *testing.T) {
100		router := NewRouter(openTestStore(t))
101	
102		recorder := postEventBody(t, router,
103			`{"account":"  alice  ","operation":"login","resource":"console","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`)
104		if recorder.Code != http.StatusCreated {
105			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
106		}
107		if event := decodeEvent(t, recorder); event["account"] != "  alice  " {
108			t.Fatalf("account = %q, want original text kept", event["account"])
109		}
110	}
111	
112	func TestPostEventRejectsInvalidInput(t *testing.T) {
113		cases := map[string]string{
114			"malformed json":      `{"account":`,
115			"trailing value":      `{} {}`,
116			"non object array":    `[]`,
117			"non object scalar":   `42`,
118			"null document":       `null`,
119			"missing field":       `{"account":"a","operation":"o","resource":"r","occurred_at":"2026-10-05T00:00:00Z"}`,
120			"null field":          `{"account":null,"operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
121			"wrong type":          `{"account":1,"operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
122			"blank account":       `{"account":"   ","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
123			"forbidden hash":      `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","hash":"x"}`,
124			"forbidden prev_hash": `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","prev_hash":"x"}`,
125			"unknown field":       `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","note":"x"}`,
126			"time no zone":        `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00"}`,
127			"time bad date":       `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-02-30T00:00:00Z"}`,
128			"time leap second":    `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2016-12-31T23:59:60Z"}`,
129			"time bad shape":      `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05 00:00:00Z"}`,
130			"seq fraction":        `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":1.5}`,
131			"seq exponent":        `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":1e3}`,
132			"seq string":          `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":"1"}`,
133			"seq zero":            `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":0}`,
134			"seq negative":        `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":-1}`,
135			"seq null":            `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":null}`,
136		}
137		for name, body := range cases {
138			t.Run(name, func(t *testing.T) {
139				router := NewRouter(openTestStore(t))
140				recorder := postEventBody(t, router, body)
141				if recorder.Code != http.StatusBadRequest {
142					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body.String())
143				}
144				var decoded struct {
145					Error struct {
146						Code    string `json:"code"`
147						Message string `json:"message"`
148					} `json:"error"`
149				}
150				if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
151					t.Fatalf("decode error body: %v", err)
152				}
153				if decoded.Error.Code != "invalid_audit_input" {
154					t.Fatalf("code = %q", decoded.Error.Code)
155				}
156				if decoded.Error.Message == "" {
157					t.Fatal("message must be non-empty")
158				}
159			})
160		}
161	}
