221	func TestPostEventConcurrentAppendsStayGapFree(t *testing.T) {
222		router := NewRouter(openTestStore(t))
223	
224		const writers = 16
225		codes := make([]int, writers)
226		seqs := make([]float64, writers)
227		var wg sync.WaitGroup
228		for i := 0; i < writers; i++ {
229			wg.Add(1)
230			go func(i int) {
231				defer wg.Done()
232				recorder := postEventBody(t, router, validEventBody())
233				codes[i] = recorder.Code
234				if recorder.Code == http.StatusCreated {
235					seqs[i] = decodeEvent(t, recorder)["seq"].(float64)
236				}
237			}(i)
238		}
239		wg.Wait()
240	
241		seen := map[float64]bool{}
242		for i := 0; i < writers; i++ {
243			if codes[i] != http.StatusCreated {
244				t.Fatalf("writer %d: status = %d, want 201", i, codes[i])
245			}
246			if seen[seqs[i]] {
247				t.Fatalf("duplicate seq %v", seqs[i])
248			}
249			seen[seqs[i]] = true
250		}
251		for seq := float64(1); seq <= writers; seq++ {
252			if !seen[seq] {
253				t.Fatalf("seq %v missing, got %v", seq, seen)
254			}
255		}
256	}
