272	// storedEvent is one row read back from the events table.
273	type storedEvent struct {
274		seq        int64
275		occurredAt string
276		prevHash   string
277		hash       string
278	}
279	
280	// readStoredEvents opens the database file directly and returns every
281	// persisted record in seq order, so tests verify what was actually saved.
282	func readStoredEvents(t *testing.T, path string) []storedEvent {
283		t.Helper()
284		db, err := sql.Open("sqlite", path)
285		if err != nil {
286			t.Fatalf("open sqlite: %v", err)
287		}
288		defer db.Close()
289		rows, err := db.Query("SELECT seq, occurred_at, prev_hash, hash FROM events ORDER BY seq")
290		if err != nil {
291			t.Fatalf("query events: %v", err)
292		}
293		defer rows.Close()
294		var events []storedEvent
295		for rows.Next() {
296			var e storedEvent
297			if err := rows.Scan(&e.seq, &e.occurredAt, &e.prevHash, &e.hash); err != nil {
298				t.Fatalf("scan event: %v", err)
299			}
300			events = append(events, e)
301		}
302		if err := rows.Err(); err != nil {
303			t.Fatalf("iterate events: %v", err)
304		}
305		return events
306	}
