430			{"2026-10-05T01:00:00.2500+08:00", "2026-10-04T17:00:00.2500Z"}, // fraction digits and trailing zeros kept
431			{"2026-10-05T08:30:00Z", "2026-10-05T08:30:00Z"},                // Z input unchanged
432			{"2026-10-04T23:00:00-02:00", "2026-10-05T01:00:00Z"},           // negative offset forward
433		}
434		for _, tc := range cases {
