446	func TestPostEventRejectedTimeLeavesChainUntouched(t *testing.T) {
447		path := filepath.Join(t.TempDir(), "service.db")
448	
449		st, err := store.Open(path)
450		if err != nil {
451			t.Fatalf("open: %v", err)
452		}
453		router := NewRouter(st)
454	
455		// Out-of-range times, with and without seq, are all rejected.
456		wantInvalidTime(t, router, `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"0000-01-01T00:00:00+00:01"}`)
457		wantInvalidTime(t, router, `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"9999-12-31T23:59:59-00:01","seq":1}`)
458		wantInvalidTime(t, router, `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"9999-12-31T23:59:59-00:01","seq":9}`)
459	
460		// The rejections consumed no sequence number and moved no chain tail.
461		recorder := postEventBody(t, router, validEventBody())
462		if recorder.Code != http.StatusCreated {
463			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
464		}
465		first := decodeEvent(t, recorder)
466		if first["seq"] != float64(1) || first["prev_hash"] != strings.Repeat("0", 64) {
467			t.Fatalf("first = %v, want seq 1 chained to genesis", first)
468		}
469		st.Close()
470	
471		// Only the valid append was persisted.
472		stored := readStoredEvents(t, path)
473		if len(stored) != 1 {
474			t.Fatalf("stored %d events, want 1", len(stored))
475		}
476		if stored[0].seq != 1 || stored[0].occurredAt != "2026-10-05T00:30:00Z" || stored[0].hash != first["hash"] {
477			t.Fatalf("stored event = %+v, want the valid append", stored[0])
478		}
479	
480		// After a close and reopen the chain continues from the same tail.
481		st, err = store.Open(path)
482		if err != nil {
483			t.Fatalf("reopen: %v", err)
484		}
485		defer st.Close()
486		second := decodeEvent(t, postEventBody(t, NewRouter(st), validEventBody()))
487		if second["seq"] != float64(2) || second["prev_hash"] != first["hash"] {
488			t.Fatalf("after reopen: seq = %v prev_hash = %v, want 2 and %v", second["seq"], second["prev_hash"], first["hash"])
489		}
490		stored = readStoredEvents(t, path)
491		if len(stored) != 2 || stored[1].hash != second["hash"] {
492			t.Fatalf("stored events after reopen = %+v", stored)
493		}
