func hasLoneSurrogateEscape(body []byte) bool {
    inString := false
    for i := 0; i < len(body); i++ {
        c := body[i]
        if !inString {
            if c == '"' {
                inString = true
            }
            continue
        }
        switch c {
        case '"':
            inString = false
        case '\\':
            if i+1 >= len(body) {
                return false // malformed; JSON decode will reject
            }
            next := body[i+1]
            if next != 'u' {
                i++ // skip escaped char (handles \\)
                continue
            }
            if i+5 >= len(body) {
                return false // malformed; decode rejects
            }
            hex := body[i+2 : i+6]
            v, ok := parseHex4(hex)
            if !ok {
                return false // decode rejects
            }
            if v >= 0xD800 && v <= 0xDBFF {
                // high surrogate: must be followed by \uDC00-\uDFFF
