						i += 11
						continue
					}
				}
				return true
			case v >= 0xDC00 && v <= 0xDFFF:
				// A low surrogate without a preceding high surrogate.
				return true
			}
			i += 5
		}
	}
	return false
}

// parseHex4 reads exactly four hexadecimal digits, either case.
func parseHex4(b []byte) (int, bool) {
	v := 0
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v += int(c - '0')
		case c >= 'a' && c <= 'f':
			v += int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v += int(c-'A') + 10
		default:
			return 0, false
		}
	}
	return v, true
}

